    height=Number(info.thumbheight || info.height || 0);
    mediaType='photo';

    const nonPhotoWords = /\b(diagrams?|schematics?|infographics?|flowcharts?|vectors?|clipart|drawings?|renders?|rendering|plots?|charts?|book covers?|brochures?|posters?|slides?|documents?|manuals?|crystal structures?|molecular structures?|atomic structures?|unit cells?|lattice diagrams?)\b/i;
    const assetTypeEvidence = [p.title,objectName,categories].filter(Boolean).join(' ');
    if (
      mime.includes('svg') ||
      nonPhotoWords.test(assetTypeEvidence)
    ) {
      extraReject='wikimedia_non_photographic_asset';
    }
  }

  if (!downloadUrl.startsWith('https://') || !(width > 0 && height > 0)) continue;

  // Long Commons descriptions often contain taxonomy/history and contrasts
  // about subjects that are not depicted. Only the image title/object name
  // and classification categories establish the subject; prose remains weak context.
  const strongMetadataText = [p.title, objectName, categories].filter(Boolean).join(' ');

  const scored = scoreCandidate(
    ctx,
    metadataText,
    mediaType,
    width,
    height,
    i+1,
    extraReject,
    strongMetadataText
  );

  candidates.push({
    provider_asset_id:String(p.pageid),
    provider_rank:i+1,
    media_type:mediaType,
    source_url:String(info.descriptionurl || info.descriptionshorturl || ''),
    download_url:downloadUrl,
    preview_url:previewUrl || null,
    author:artist || null,
    author_url:String(info.descriptionurl || '') || null,
    license_name:licenseName,
    license_url:licenseUrl,
    width,
    height,
    duration_ms:durationMs,
    metadata_text:metadataText,
    relevance_score:scored.relevance_score,
    rejected:scored.rejected,
    rejection_reason:scored.rejection_reason,
    metadata:{
      title:p.title ?? null,
      mime,
      original_bytes:info.size ?? null,
      credit:stripHtml(metaValue(ext,'Credit')) || null,
      attribution_required:metaValue(ext,'AttributionRequired') || null,
      query:ctx.query,
    },
  });
}

return {json:{
  visual_run_id:ctx.visual_run_id,
  shot_uuid:ctx.shot_uuid,
  provider:'wikimedia',
  query_index:ctx.query_index,
  query_text:ctx.query,
  endpoint_kind:ctx.endpoint_kind,
  http_status:status,
  response_headers:{
    'retry-after':headers['retry-after'] ?? null,
    'cache-control':headers['cache-control'] ?? null,
    'date':headers.date ?? null,
    'content-type':headers['content-type'] ?? null,
    'provider-degraded':status === 200 ? null : true,
  },
  candidates,
}};

