parameters.jsCode:
const row=$input.first().json;
let selections=row.selections_json;
if(typeof selections==='string') selections=JSON.parse(selections);
if(!Array.isArray(selections) || !selections.length) throw new Error('M8 selections_json is empty');
return selections.map((s)=>({json:s}));

const ctx=$('Expand Selected Visuals').item.json;
const begin=$('Begin Visuals').first().json;
const response=$json??{};
const body=response.body&&typeof response.body==='object'?response.body:response;
let status=Number(response.statusCode??response.status??0);
if(!status&&body.status==='ready') status=201;
const prefix='/data/visuals/' + $('When Executed by Another Workflow').first().json.job_id + '/' + ctx.shot_uuid + '/selected.';
const ok=
  status===201 &&
  body.status==='ready' &&
  String(body.shot_id||'')===String(ctx.shot_uuid) &&
  String(body.provider||'')===String(ctx.provider) &&
  String(body.provider_asset_id||'')===String(ctx.provider_asset_id) &&
  String(body.media_type||'')===String(ctx.media_type) &&
  String(body.storage_path||'').startsWith(prefix) &&
  /^[0-9a-f]{64}$/.test(String(body.sha256||'')) &&
  Number(body.bytes)>0 &&
  Number(body.width)>0 &&
  Number(body.height)>0 &&
  typeof body.mime_type==='string' && body.mime_type.length>0 &&
  typeof body.codec==='string' && body.codec.length>0 &&
  (ctx.media_type!=='video' || Number(body.duration_ms)>0);
const message=body?.message??body?.error??response?.error?.message??response?.message??'selected visual download failed validation';
return {json:{
  visual_run_id:String(begin.visual_run_id),
  selection_id:String(ctx.selection_id),
  download_success:ok,
  asset:ok?body:{},
  error_message:ok?'':String(message).slice(0,3500),
}};

const begin = $('Begin Visuals').first().json;
const source = $json ?? {};
const errorObject =
  source.error && typeof source.error === 'object' && !Array.isArray(source.error)
    ? source.error
    : {};
const message = [
  source.error_message,
  errorObject.message,
  source.message,
  source.description,
  typeof source.error === 'string' ? source.error : null,
].find((v) => typeof v === 'string' && v.trim().length > 0)
  ?? 'unspecified M8 visual failure';

return {json:{
  visual_run_id:String(begin.visual_run_id || ''),
  error_message:('M8 visuals failed: ' + message.trim()).slice(0,4000),
}};
